CREATE TABLE IF NOT EXISTS question_answer (
                                 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                 question VARCHAR(1000) NOT NULL,
                                 answer VARCHAR(5000) NOT NULL
);

INSERT INTO question_answer (question, answer) VALUES
('По каким причинам студента могут отчислить из университета?',
'Студент может быть отчислен:
- в случае невыполнения обязанностей по добросовестному освоению образовательной программы и выполнению учебного плана;
- в случае установления нарушения порядка приёма в Университет, повлекшего по вине обучающегося его незаконное зачисление в Университет;
- в случае просрочки оплаты стоимости платных образовательных услуг;
- в случае, если надлежащее исполнение обязательства по оказанию платных образовательных услуг стало невозможным вследствие действий (бездействия) обучающегося.'),

('Что делать, если студент хочет отчислиться добровольно?',
'Основанием для отчисления по собственному желанию, в том числе по состоянию здоровья, в связи с призывом в Вооружённые силы РФ, является письменное заявление по установленной форме, подаваемое в деканат факультета/дирекцию института (филиала)/Многопрофильного колледжа, с приложением документов, подтверждающих причины отчисления (медицинская справка, документ из военного комиссариата и т.п.).
Заявление об отчислении согласовывается с деканом/директором, Департаментом образовательной политики, Управлением международных связей (для иностранных обучающихся), Департаментом экономического развития приоритетных проектов и платных образовательных услуг (для платников).'),

('Могут ли отчислить студента, если он имеет только одну задолженность?',
'Да, могут. Отчисление осуществляется в том числе, если:
- обучающийся, имеющий академическую задолженность, не ликвидировал её в установленные сроки (до 15 апреля после зимней сессии, до 15 ноября после летней сессии);
- обучающийся не прошёл итоговое аттестационное испытание в связи с неявкой по неуважительной причине;
- обучающийся не прошёл одно и более итоговое аттестационное испытание;
- обучающийся без уважительных причин не посещал учебные занятия в течение 30 календарных дней подряд;
- обучающийся не посещал в течение семестра более 25% занятий по отдельным дисциплинам;
- обучающийся не ликвидировал академическую задолженность при ликвидации академической разницы в установленные сроки;
- обучающийся не вышел из академического отпуска (отпуска по беременности и родам, отпуска по уходу за ребёнком) без уважительной причины после окончания отпуска в установленное время.'),

('Могут ли отчислить студента во время болезни?',
'Нет, не могут. Не допускается отчисление обучающегося по инициативе Университета во время его болезни, каникул, академического отпуска, отпуска по беременности и родам, отпуска по уходу за ребёнком.'),

('Кто имеет право на восстановление в вузе?',
'Лицо, отчисленное по собственной инициативе до завершения освоения образовательной программы, имеет право на восстановление в Университет в течение 5 лет после отчисления, но не ранее завершения учебного года (семестра), в котором оно было отчислено, с сохранением основы обучения (бесплатная или платная) при наличии вакантных мест.
Лицо, отчисленное по инициативе Университета, имеет право на восстановление в Университет на платную основу (при наличии вакантных мест) в течение 5 лет после отчисления, но не ранее завершения учебного года (семестра), в котором оно было отчислено.
На восстановление на бесплатную основу (один раз, при наличии вакантных бюджетных мест) в течение 5 лет могут претендовать:
- дети-сироты;
- дети, оставшиеся без попечения родителей;
- лица из числа детей-сирот и детей, оставшихся без попечения родителей;
- лица, потерявшие в период обучения обоих родителей или единственного родителя;
- инвалиды и лица с ОВЗ;
- участники СВО и члены их семей.'),

('Кто может быть восстановлен на бесплатную основу обучения?',
'Лицо, отчисленное по собственной инициативе до завершения освоения образовательной программы, имеет право на восстановление в Университет в течение 5 лет после отчисления, но не ранее завершения учебного года (семестра), в котором оно было отчислено, с сохранением бесплатной основы обучения (при наличии вакантных мест).
Один раз на бесплатную основу (при наличии вакантных бюджетных мест) в течение 5 лет могут быть восстановлены лица, отчисленные по инициативе Университета, относящиеся к следующим категориям:
- дети-сироты;
- дети, оставшиеся без попечения родителей;
- лица из числа детей-сирот и детей, оставшихся без попечения родителей;
- лица, потерявшие в период обучения обоих родителей или единственного родителя;
- инвалиды и лица с ОВЗ;
- участники СВО и члены их семей.'),

('Какие документы нужны для восстановления?',
'Восстановление в число обучающихся Университета производится по личному заявлению восстанавливающегося лица приказом ректора (проректора по учебной работе/директора ИДО).
Заявление о восстановлении подаётся в деканат/дирекцию и рассматривается аттестационной комиссией в недельный срок. Определяются курс, академическая разница, сроки её ликвидации и основа обучения (платная/бесплатная), о чём делается запись на заявлении.
При восстановлении формируется индивидуальный учебный план с учётом разницы в учебных планах.
Заявление согласовывается с деканом/директором, Департаментом образовательной политики, Управлением международных связей (для иностранных обучающихся), а при восстановлении на платную основу также с Департаментом экономического развития приоритетных проектов и платных образовательных услуг, заключается договор и вносится оплата.
Для ликвидации разницы выдаются экзаменационные листы с указанием сроков. Обучающийся обязан соблюдать установленные сроки.
Проект приказа о восстановлении подготавливается и согласуется в установленном порядке с использованием электронного документооборота.'),

('Что делать, если не прошёл ГИА?',
'Обучающимся, завершившим освоение образовательной программы и не подтвердившим соответствие требованиям стандарта при прохождении одного или нескольких итоговых аттестационных испытаний, предоставляется право восстановления в число обучающихся и прохождения повторных итоговых аттестационных испытаний.
Повторные испытания назначаются не ранее чем через 10 месяцев и не позднее чем через 5 лет после первой итоговой аттестации, не более двух раз.
Для повторного прохождения необходимо подать заявление о восстановлении. По решению выпускающей кафедры может быть сохранена прежняя тема ВКР или утверждена новая. Восстановление осуществляется на период, предусмотренный учебным графиком для итоговых испытаний.'),

('Можно ли перевестись с платной формы обучения на бюджетную?',
'Да, можно. Перевод обучающихся допускается с любой формы обучения на любую форму обучения.
Перевод в Университет как принимающую организацию осуществляется при наличии вакантных мест для перевода.
Количество вакантных мест для перевода определяется Университетом по программам, формам и курсам обучения, с указанием мест, финансируемых за счёт бюджета и по договорам об образовании.'),

('Кто имеет право на переход с платного обучения на бесплатное?',
'Право на переход с платного обучения на бесплатное имеет обучающийся по договору за счёт средств физических и (или) юридических лиц, не имеющий на момент подачи заявления академической задолженности, дисциплинарных взысканий и задолженности по оплате обучения, при наличии:
а) оценок за два последних семестра «отлично» или «отлично» и «хорошо» или «хорошо»;
б) отнесения к льготным категориям (дети-сироты, дети без попечения родителей, граждане до 20 лет с одним родителем-инвалидом I группы при низком доходе, женщины, родившие ребёнка в период обучения);
в) утраты в период обучения одного или обоих родителей (законных представителей) или единственного родителя.'),

('Можно ли перевестись с платного обучения на бесплатное, если учишься на «хорошо» и «удовлетворительно»?',
'Нет. Право на переход с платного обучения на бесплатное имеет студент, сдавший экзамены за два последних семестра на оценки «отлично» или «отлично» и «хорошо» или «хорошо».'),

('Где можно узнать о наличии свободных бюджетных мест для перевода с платного обучения на бесплатное?',
'Информация о количестве вакантных бюджетных мест для перехода с платного обучения на бесплатное и сроках подачи заявлений размещается в информационно-телекоммуникационных сетях, в том числе на официальном сайте университета в сети Интернет.'),

('Куда нужно обратиться, чтобы перевестись с платного обучения на бесплатное?',
'Обучающийся, желающий перейти на вакантное бюджетное место, подаёт в деканат (дирекцию) заявление на имя ректора о переходе с платного обучения на бесплатное в течение двух недель после размещения информации о вакантных местах.
К заявлению прилагаются документы, подтверждающие льготную категорию (справки о составе семьи, из органов соцзащиты, об инвалидности и др.), а также документы, подтверждающие особые достижения в учебной, научной, общественной, культурно-творческой и спортивной деятельности (грамоты, дипломы, публикации и т.п.).'),

('Можно ли перевестись на другой факультет, на другое направление подготовки до первой сессии?',
'Нет. Перевод обучающихся допускается не ранее чем после прохождения первой промежуточной аттестации в Университете (при переводе внутри Университета или в принимающую организацию) и в исходной организации (при переводе в Университет).'),

('Что нужно, чтобы перевестись в МГУ им. Н.П. Огарёва из другого вуза?',
'Необходимо подать в деканат/дирекцию заявление о переводе на имя проректора по учебной работе с приложением справки о периоде обучения и иных документов, подтверждающих индивидуальные достижения.
Деканат/дирекция оценивают документы, определяют перечень дисциплин, практик и исследований, которые могут быть перезачтены, и период, с которого обучающийся будет допущен к обучению.
При избытке заявлений проводится конкурсный отбор по среднему баллу и достижениям. По результатам принимается решение о зачислении на вакантные места.
При положительном решении выдаётся справка о переводе с указанием уровня образования, кода и наименования программы, заверенная печатью, и перечнем дисциплин/практик для перезачёта. Эта справка вместе с заявлением, выпиской из приказа об отчислении и документом о предшествующем образовании подаётся для подготовки приказа о зачислении.'),

('Как можно перевестись с одной образовательной программы университета на другую?',
'Перевод осуществляется по личному заявлению обучающегося на имя проректора по учебной работе и проводится на основе аттестации, которую проводит аттестационная комиссия принимающего факультета (института/филиала).
Для переаттестации дисциплин выдаётся аттестационная ведомость с перечнем дисциплин/практик, подлежащих перезачёту.
Аттестация проводится в форме собеседования или иной форме, определённой комиссией. Определяется разница в учебных планах, перечень дисциплин для перезачёта и неизученных дисциплин/практик, по которым нужно пройти испытания, и сроки их ликвидации.
Переаттестация оформляется приказом по Университету. Наличие несданных дисциплин по истечении сроков приравнивается к академическим задолженностям.'),

('Сохраняются ли зачётная книжка и студенческий билет при переходе с одной образовательной программы Университета на другую?',
'При незначительной разнице в учебных планах обучающемуся могут быть сохранены прежние документы (зачётная книжка и студенческий билет) с отметкой о переводе. В зачётную книжку вносятся записи о ликвидации разницы и соответствующие оценки.
При значительной разнице выдаются новые документы. В новую зачётную книжку вносятся записи о перезачтённых дисциплинах, практиках, курсовых работах с оценками.'),

('Когда начинается и заканчивается приём заявлений на перевод?',
'Перевод обучающихся не зависит от периода учебного года и осуществляется при наличии вакантных мест для перевода.'),

('Нужно ли сдавать экзамены при переводе?',
'Если заявлений о переводе больше, чем вакантных мест, проводится конкурсный отбор по среднему баллу и достижениям.
Перевод осуществляется на основе аттестации, которую проводит аттестационная комиссия принимающего факультета (института/филиала). Для переаттестации дисциплин выдаётся аттестационная ведомость.
Аттестация может проводиться в форме собеседования или иной форме. В ходе аттестации определяется перечень неизученных дисциплин/практик, по которым необходимо пройти аттестационные испытания, и сроки ликвидации разницы.'),

('Кто имеет право на академический отпуск?',
'Академический отпуск предоставляется обучающимся в связи с временной невозможностью освоения образовательной программы в случае призыва на военную службу или заключения контракта о прохождении военной службы, по медицинским показаниям, а также в иных исключительных случаях, в том числе по семейным обстоятельствам и в связи со стихийными бедствиями.'),

('Какой максимальный срок академического отпуска?',
'Продолжительность академического отпуска единовременно не может превышать 12 календарных месяцев, за исключением отпуска в связи с прохождением военной службы или по медицинским показаниям, срок которого не может превышать 2 года.'),

('Сколько раз можно брать академический отпуск?',
'Количество академических отпусков, предоставляемых обучающемуся в период обучения по соответствующей образовательной программе, не ограничено.'),

('Что нужно для оформления академического отпуска?',
'Основанием является личное заявление на имя проректора по учебной работе и документ, подтверждающий основания:
- медицинское заключение из медорганизации (для отпуска по медицинским показаниям);
- мобилизационное предписание, повестка, копия контракта о прохождении военной службы (для отпуска в связи с военной службой);
- иной документ, подтверждающий основания предоставления академического отпуска (при наличии).'),

('Как быть, если обучающийся не может лично представить заявление и документы для оформления академического отпуска?',
'В этом случае заявление может быть подано законным представителем, лицом по доверенности, через операторов почтовой связи заказным отправлением с уведомлением о вручении, а также иным доступным способом.'),

('Можно ли оформить академический отпуск, если обучающийся не может представить документы, подтверждающие наличие основания для него?',
'Да, можно. Для таких случаев приказом ректора утверждается Комиссия. По результатам рассмотрения заявления и прилагаемых документов (при наличии) Комиссия принимает решение о предоставлении академического отпуска или об отказе.'),

('Может ли студент, находясь в академическом отпуске, посещать занятия?',
'Нет. Обучающийся в период академического отпуска освобождается от обязанностей, связанных с освоением образовательной программы, и не допускается к образовательному процессу до его завершения.'),

('Может ли студент прервать академический отпуск?',
'Да, может. Академический отпуск может быть завершён досрочно на основании заявления обучающегося. В таком случае допуск к обучению осуществляется приказом проректора по учебной работе.'),

('Нужно ли платить за обучение во время академического отпуска?',
'Нет. Если обучающийся обучается по договору за счёт средств физических и (или) юридических лиц, во время академического отпуска плата за обучение с него не взимается.'),

('Что делать, если на момент возвращения студента из академического отпуска образовательная программа, по которой он обучался, не реализуется?',
'Если программа по соответствующей форме обучения, направленности, специализации или направлению подготовки к моменту выхода из отпуска не реализуется, обучающемуся предлагается перевод на иную форму обучения либо другую образовательную программу с сохранением бюджетной (при наличии мест) или платной основы обучения.'),

('Кто имеет право на обучение по индивидуальному графику?',
'Право на обучение по индивидуальному графику имеют обучающиеся, которые:
- имеют детей до 3 лет и оформили отпуск по уходу за ребёнком с одновременным обучением по индивидуальному графику;
- находятся в отпуске по беременности и родам;
- имеют соответствующие медицинские показания;
- совмещают учёбу с работой по профилю направления подготовки, приобретают опыт профессиональной деятельности и не имеют академических задолженностей.'),

('Как получить зачёт «автоматом»?',
'В качестве поощрения в соответствии с Положением о БРС преподаватель имеет право выставлять отдельным обучающимся зачёт по результатам текущего контроля без самой процедуры сдачи зачёта.'),

('Сколько времени студенту даётся на подготовку устного ответа на экзамене?',
'Время подготовки устного ответа должно составлять не менее 30 минут, а время ответа обучающегося — не более 15 минут.'),

('Может ли быть перенесён срок экзаменационной сессии студенту-заочнику?',
'Обучающимся заочной формы обучения срок экзаменационной сессии может быть перенесён только по уважительным причинам (болезнь, семейные обстоятельства, участие в соревнованиях, командировка и др.) при наличии подтверждающих документов. В таких случаях устанавливаются индивидуальные сроки предоставления дополнительного учебного отпуска.'),

('Как можно сдать сессию досрочно?',
'Для досрочной сдачи сессии обучающийся пишет заявление на имя проректора по учебной работе с указанием причин переноса сроков и подтверждающими документами. Заявление визируется деканом/директором и учебно-методическим управлением. В случае положительного решения издаётся приказ и обучающемуся выдаются экзаменационные листы. Досрочная сдача сессии разрешается не ранее чем за месяц до окончания теоретического обучения текущего семестра.'),

('Кто имеет право продлить сессию?',
'Обучающийся, находившийся в период промежуточной аттестации на стационарном или амбулаторном лечении, имеет право на её продление.'),

('Куда нужно обратиться студенту, чтобы продлить сессию?',
'Нужно обратиться в течение 2 дней после закрытия больничного листа в деканат (дирекцию) с заявлением установленного образца. Приказ об установлении индивидуальных сроков промежуточной аттестации оформляется деканатом/дирекцией.'),

('На какой период можно продлить сессию?',
'Промежуточная аттестация продлевается на срок, указанный в подтверждающем документе (заключение врачебной комиссии или справка установленного образца).'),

('Что будет, если студент не придёт на экзамен?',
'Обучающийся, не явившийся по уважительной причине, обязан представить в деканат/дирекцию оправдательные документы в течение двух дней с момента устранения причины. Ему выдаются экзаменационные листы для сдачи.
При отсутствии официальных документов к окончанию сессии причина неявки считается неуважительной, и обучающийся считается имеющим академическую задолженность.'),

('Сколько раз можно пересдавать зачёт/экзамен?',
'Обучающиеся, имеющие академическую задолженность, вправе пройти повторную промежуточную аттестацию не более двух раз в установленные сроки (во второй раз на комиссии).'),

('Когда можно пересдать зачёт/экзамен?',
'Повторная промежуточная аттестация проводится как в период каникул, так и в период освоения образовательной программы. В этот период не включается время болезни обучающегося, его нахождение в академическом отпуске или отпуске по беременности и родам.'),

('Что делать, если не выполнил программу практики по уважительной причине?',
'Обучающиеся, не выполнившие программу практики по уважительной причине, направляются на практику повторно в свободное от учёбы время при условии согласия базы практики принять обучающегося.'),

('Можно ли пересдать экзамен на более высокую оценку?',
'Пересдача экзаменов (дифференцированных зачётов) в период сессии на более высокую оценку не допускается.
Пересдача на более высокую оценку (не более 3 дисциплин) возможна после сдачи последней сессии и, как правило, после всех практик до начала итоговых аттестационных испытаний по решению проректора по учебной работе при согласии декана/директора и учебно-методического управления. Необходимо подать заявление с указанием дисциплины и имеющейся оценки.'),

('Можно ли пересдать курсовую работу?',
'Нет. Не допускается пересдача курсовых работ (проектов) и практик.'),

('Что такое индивидуальный график обучения?',
'Индивидуальный график обучения (посещения занятий) — это форма организации обучения, при которой часть дисциплин учебного плана осваивается самостоятельно. Он не отменяет необходимость выполнения в полном объёме работ, предусмотренных рабочими программами дисциплин, практик и программы итоговой аттестации.'),

('Когда можно оформить индивидуальный график?',
'Обучающимся бакалавриата и специалитета индивидуальный график предоставляется после первого семестра; обучающимся магистратуры — с первого семестра.'),

('Как оформить индивидуальный график?',
'Для оформления индивидуального графика обучения нужно написать заявление на имя проректора по учебной работе. К заявлению прилагаются индивидуальный учебный график и индивидуальные графики прохождения контрольных мероприятий (рейтинг-планы дисциплин), согласованные с преподавателями.'),

('Могут ли отчислить из-за пропусков?',
'Да. Студент, не посещающий занятия без уважительных причин 30 календарных дней подряд или отсутствующий без уважительных причин более чем на 25% занятий по отдельным дисциплинам в семестре, может быть отчислен как невыполняющий обязанности по добросовестному освоению образовательной программы и выполнению учебного плана. Основанием служат подтверждающие документы (служебная записка декана/директора и др.).');
